'use strict';

let deepClone;
try {
  const mod = require('../../../src/options/clone');
  deepClone = mod && (mod.deepClone || mod.default);
} catch (e) {
  throw e;
}
if (typeof deepClone !== 'function') {
  throw new Error('deepClone function not found in module');
}

describe('deepClone', () => {
  test('clones primitive values by value', () => {
    expect(deepClone(1)).toBe(1);
    expect(deepClone('str')).toBe('str');
    expect(deepClone(true)).toBe(true);
    expect(deepClone(null)).toBeNull();
    expect(deepClone(undefined)).toBeUndefined();
  });

  test('clones arrays deeply', () => {
    const input = [1, [2, 3], { a: 4 }];
    const result = deepClone(input);

    expect(result).not.toBe(input);
    expect(result).toEqual([1, [2, 3], { a: 4 }]);
    expect(result[1]).not.toBe(input[1]);
    expect(result[2]).not.toBe(input[2]);
    expect(result[2].a).toBe(4);
  });

  test('clones plain objects deeply', () => {
    const input = { x: 1, y: { z: 2 } };
    const out = deepClone(input);
    expect(out).not.toBe(input);
    expect(out.x).toBe(1);
    expect(out.y).not.toBe(input.y);
    expect(out.y.z).toBe(2);
  });

  test('non-plain objects are returned as-is', () => {
    const date = new Date(2020, 0, 1);
    const dateClone = deepClone(date);
    expect(dateClone).toBe(date);

    const fn = function () {};
    const fnClone = deepClone(fn);
    expect(fnClone).toBe(fn);
  });

  test('complex nested structure clones all nested elements', () => {
    const input = {
      a: [1, { b: 2 }, [3, 4]],
      c: new Date(2020, 5, 15),
    };
    const out = deepClone(input);
    expect(out).not.toBe(input);
    expect(out.a).not.toBe(input.a);
    expect(out.a[1]).not.toBe(input.a[1]);
    expect(out.a[1].b).toBe(2);
    expect(out.c).toBe(input.c);
  });
});

